int ext4_orphan_add(handle_t *handle, struct inode *inode) {
    struct super_block *sb = inode->i_sb;
    struct ext4_sb_info *sbi = EXT4_SB(sb);
    struct ext4_inode_info *ei = EXT4_I(inode);
    int err = 0;
    int need_commit = 0;
    __u32 inum = inode->i_ino;

    if (EXT4_SB(sb)->s_journal == NULL)
        return 0;

    if (ei->i_orphan.next != NULL)
        return 0;

    if (!S_ISREG(inode->i_mode) && !S_ISDIR(inode->i_mode) &&
        !S_ISLNK(inode->i_mode))
        return 0;

    err = ext4_journal_get_write_access(handle, ei->i_bh, GFP_NOFS);
    if (err)
        return err;

    err = ext4_reserve_inode(handle, sbi, 1);
    if (err)
        return err;

    if (sbi->s_orphan_head != inum) {
        ext4_set_orphan_list(inode, sbi->s_orphan_head);
        sbi->s_orphan_head = inum;
        ext4_set_super_orphan_list(sb, inum);
        mark_inode_dirty(handle, inode);
        need_commit = 1;
    }

    list_add(&ei->i_orphan, &sbi->s_orphan);
    unlock_orphan_list(sbi);

    if (need_commit) {
        err = ext4_journal_stop(handle);
        handle = start_transaction(sb);
        if (IS_ERR(handle))
            return PTR_ERR(handle);
    }

    return 0;
}

int ext4_add_orphan_entry(handle_t *handle, struct inode *inode) {
    struct super_block *sb = inode->i_sb;
    struct ext4_super_block *es = EXT4_SB(sb)->s_es;
    int err = 0;

    if (!EXT4_HAS_JOURNAL(sb)) {
        return -EINVAL;
    }

    mutex_lock(&EXT4_I(inode)->i_orphan_lock);

    if (ext4_has_orphan(inode)) {
        err = -EEXIST;
        goto out_unlock;
    }

    if (!S_ISREG(inode->i_mode) && !S_ISDIR(inode->i_mode) && !S_ISLNK(inode->i_mode)) {
        err = -EINVAL;
        goto out_unlock;
    }

    err = ext4_journal_get_write_access(handle, inode->i_ino, sb);
    if (err < 0)
        goto out_unlock;

    err = ext4_journal_space_reserver(handle, 1);
    if (err < 0)
        goto out_unlock;

    if (!ext4_has_orphan(inode)) {
        es->s_last_orphan = cpu_to_le32(inode->i_ino);
        err = ext4_mark_super_dirty(handle, sb);
        if (err < 0)
            goto out_unlock;
    }

    list_add_tail(&EXT4_I(inode)->i_orphan, &EXT4_SB(sb)->s_orphan);
    ext4_set_orphan(inode);

out_unlock:
    mutex_unlock(&EXT4_I(inode)->i_orphan_lock);
    return err;
}

int ext4_orphan_add(handle_t *handle, struct inode *inode) {
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_super_block *es;
    int err = 0;
    int update = 0;

    if (!EXT4_HAS_JOURNAL(inode->i_sb))
        return 0;

    if (inode->i_nlink != 0)
        return 0;

    if (!S_ISREG(inode->i_mode) && !S_ISDIR(inode->i_mode) &&
        !S_ISLNK(inode->i_mode))
        return 0;

    spin_lock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
    if (!list_empty(&ei->i_orphan)) {
        spin_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
        return 0;
    }

    list_add_tail(&ei->i_orphan, &EXT4_SB(inode->i_sb)->s_orphan);
    spin_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);

    err = ext4_journal_get_write_access(handle, inode->i_sb, NULL);
    if (err)
        return err;

    err = ext4_reserve_inode(handle, inode);
    if (err)
        return err;

    es = &EXT4_SB(inode->i_sb)->s_es;
    if (es->s_last_orphan == 0) {
        es->s_last_orphan = cpu_to_le32(inode->i_ino);
        update = 1;
    }

    if (update) {
        err = ext4_mark_inode_dirty(handle, inode);
        if (err)
            return err;
    }

    return 0;
}

int ext4_add_orphan (handle_t *handle, struct inode *inode) {
    int err = 0;
    struct ext4_iloc iloc;
    struct ext4_inode *raw_inode;
    struct ext4_sb_info *sbi = EXT4_SB(inode->i_sb);
    struct ext4_orphan *orphan;

    if (!EXT4_HAS_JOURNAL(inode->i_sb)) {
        return -EINVAL;
    }

    mutex_lock(&sbi->s_orphan_lock);

    if (!list_empty(&inode->i_orphan)) {
        mutex_unlock(&sbi->s_orphan_lock);
        return -EEXIST;
    }

    if (!S_ISREG(inode->i_mode) && !S_ISDIR(inode->i_mode) &&
        !S_ISLNK(inode->i_mode)) {
        mutex_unlock(&sbi->s_orphan_lock);
        return -EINVAL;
    }

    err = ext4_journal_get_write_access(handle, inode->i_ino, NULL);
    if (err < 0) {
        mutex_unlock(&sbi->s_orphan_lock);
        return err;
    }

    err = ext4_reserve_inode(handle, inode);
    if (err < 0) {
        mutex_unlock(&sbi->s_orphan_lock);
        return err;
    }

    err = ext4_get_inode_loc(inode, &iloc);
    if (err < 0) {
        mutex_unlock(&sbi->s_orphan_lock);
        return err;
    }

    raw_inode = ext4_get_inode(inode, &iloc);

    if (le32_to_cpu(raw_inode->i_flags) & EXT4_ORPHAN_FL) {
        mutex_unlock(&sbi->s_orphan_lock);
        ext4_free_inode_loc(&iloc);
        return -EEXIST;
    }

    raw_inode->i_flags = cpu_to_le32(le32_to_cpu(raw_inode->i_flags) |
                                     EXT4_ORPHAN_FL);
    err = ext4_mark_inode_dirty(handle, inode, raw_inode);
    if (err < 0) {
        mutex_unlock(&sbi->s_orphan_lock);
        ext4_free_inode_loc(&iloc);
        return err;
    }

    list_add(&inode->i_orphan, &sbi->s_orphan_list);
    mutex_unlock(&sbi->s_orphan_lock);

    ext4_free_inode_loc(&iloc);
    return err;
}

int ext4_orphan_add(handle_t *handle, struct inode *inode)
{
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_super_block *es;
    struct ext4_sb_info *sbi;
    struct list_head *head;
    int err;

    if (!ext4_journal_has_feature_compression(inode->i_sb))
        return -EINVAL;

    sbi = EXT4_SB(inode->i_sb);
    head = &sbi->s_orphan;

    spin_lock(&sbi->s_orphan_lock);

    if (!list_empty(&ei->i_list))
        goto unlock_out;

    if (!S_ISREG(inode->i_mode) && !S_ISDIR(inode->i_mode) &&
        !S_ISLNK(inode->i_mode)) {
        err = -EINVAL;
        goto unlock_out;
    }

    err = ext4_journal_get_write_access(handle, inode->i_sb, NULL);
    if (err)
        goto unlock_out;

    err = ext4_journal_space_reservation(handle, EXT4_JOURNAL_SPACE_ORPHAN,
                                         1, 0);
    if (err)
        goto unlock_out;

    es = &sbi->s_es;
    le32_add_cpu(&es->s_orphans, 1);
    ext4_set_inode_state(inode, EXT4_STATE_ORPHAN_LIST);

    err = ext4_mark_inode_dirty(handle, inode);
    if (err)
        goto undo_orphan_count;

    list_add_tail(&ei->i_list, head);

unlock_out:
    spin_unlock(&sbi->s_orphan_lock);
    return err;

undo_orphan_count:
    le32_sub_cpu(&es->s_orphans, 1);
    goto unlock_out;
}
